def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip().lower()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1).strip()

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""

        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
            if not local:
                return ""

        return f"{local}@{domain}"

    def normalize_phone(value):
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"\D", "", value)

        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""

        return digits

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value[:5]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def normalize_tags(value):
        return {
            tag.strip().lower()
            for tag in re.split(r"[;,]", value)
            if tag.strip()
        }

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    normalized = []
    for input_index, row in enumerate(rows):
        record = {
            "input_index": input_index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": normalize_email(row["email"]),
            "phone": normalize_phone(row["phone"]),
            "zip": normalize_zip(row["zip"]),
            "tags": normalize_tags(row["tags"]),
            "opted_out": is_opted_out(row["opted_out"]),
            "updated": parse_updated(row["updated"]),
            "source": row["source"].strip().lower(),
        }

        if record["email"] or record["phone"]:
            normalized.append(record)

    # Disjoint-set union for transitive matching.
    parent = list(range(len(normalized)))
    rank = [0] * len(normalized)

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return

        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root

        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1

    email_owner = {}
    phone_last_name_owner = {}

    for index, record in enumerate(normalized):
        if record["email"]:
            prior = email_owner.get(record["email"])
            if prior is None:
                email_owner[record["email"]] = index
            else:
                union(index, prior)

        if record["phone"] and record["last_name"]:
            key = (record["phone"], record["last_name"].casefold())
            prior = phone_last_name_owner.get(key)
            if prior is None:
                phone_last_name_owner[key] = index
            else:
                union(index, prior)

    groups = {}
    for index, record in enumerate(normalized):
        groups.setdefault(find(index), []).append(record)

    def choose_field(group, field):
        candidates = [record for record in group if record[field]]
        if not candidates:
            return ""
        winner = max(
            candidates,
            key=lambda record: (
                record["source"] == "manual",
                record["updated"],
                -record["input_index"],
            ),
        )
        return winner[field]

    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(record["input_index"] for record in group),
    )

    result = []
    for group in ordered_groups:
        all_tags = set()
        for record in group:
            all_tags.update(record["tags"])

        latest_updated = max(record["updated"] for record in group)

        result.append({
            "first_name": choose_field(group, "first_name"),
            "last_name": choose_field(group, "last_name"),
            "zip": choose_field(group, "zip"),
            "email": choose_field(group, "email"),
            "phone": choose_field(group, "phone"),
            "source": choose_field(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
            "updated": latest_updated.strftime("%Y-%m-%d"),
        })

    return result
